<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api,useLoad,useCommand,PageHeader,Feedback,type DataRow} from '@tradeflow/ui'
const page=ref(1),reason=ref(''),selected=ref<DataRow|null>(null),choice=ref('UPHOLD'),command=useCommand('admin-disputes')
const list=useLoad<{items:DataRow[];total:number}>(signal=>api(`/admin/disputes?page=${page.value}&pageSize=20`,{signal}))
const audits=useLoad<{items:DataRow[];total:number}>(signal=>api(`/admin/audits?page=${auditPage.value}&pageSize=20`,{signal})),auditPage=ref(1)
async function decide(){const row=selected.value;if(!row||!reason.value.trim())return;const body={decision:choice.value,reason:reason.value.trim(),version:Number(row.version)};const result=await command.run('decision:'+row.dispute_no,body,key=>api('/admin/disputes/'+row.dispute_no+'/decision',{method:'POST',body,key}));if(result!==undefined){await command.reset();selected.value=null;reason.value='';await list.reload()}}
async function next(delta:number){page.value+=delta;await list.reload()}
onMounted(()=>{void list.reload();void audits.reload()})
</script>
<template><section><PageHeader title="平台争议与审计" description="裁定沿用原售后权益和退款任务，受理后仍需查询实际执行结果。"/><div class="panel"><Feedback :error="list.error.value" :loading="list.loading.value"/><ElTable :data="list.data.value?.items||[]"><ElTableColumn prop="dispute_no" label="争议编号" min-width="220"/><ElTableColumn prop="aftersale_no" label="原售后" min-width="220"/><ElTableColumn prop="reason" label="申请依据" min-width="200"/><ElTableColumn prop="status" label="状态"/><ElTableColumn prop="decision" label="裁定"/><ElTableColumn label="操作"><template #default="{row}"><ElButton v-if="row.status==='OPEN'" @click="selected=row;reason=''">处理</ElButton></template></ElTableColumn></ElTable><div class="pagination"><button :disabled="page<=1||list.loading.value" @click="next(-1)">上一页</button><span>第{{page}}页 · 共{{list.data.value?.total??'—'}}条</span><button :disabled="page*20>=(list.data.value?.total??0)||list.loading.value" @click="next(1)">下一页</button></div></div><div v-if="selected" class="panel"><h2>裁定 {{selected.dispute_no}}</h2><p class="notice">通过或拒绝仅适用于原售后仍处于待审核状态；已执行的退款和终止授权不能逆转。退货仍须实际验收，不能靠裁定直接写入资金成功。</p><label for="decision">裁定</label><select id="decision" v-model="choice"><option value="UPHOLD">保持现有处理</option><option value="APPROVE">原金额审核通过</option><option value="REJECT">拒绝并终止原授权</option></select><label for="decision-reason">裁定依据</label><textarea id="decision-reason" v-model="reason" maxlength="1000" required/><Feedback :error="command.error.value"/><button :disabled="command.busy.value||!reason.trim()" @click="decide">提交裁定</button><button @click="selected=null">关闭</button></div><div class="panel"><h2>平台授权审计</h2><Feedback :error="audits.error.value" :loading="audits.loading.value"/><ElTable :data="audits.data.value?.items||[]"><ElTableColumn prop="actorId" label="操作者"/><ElTableColumn prop="action" label="操作"/><ElTableColumn prop="businessNo" label="业务编号"/><ElTableColumn prop="reason" label="依据"/><ElTableColumn prop="createdAt" label="时间"/></ElTable><div class="pagination"><button :disabled="auditPage<=1" @click="auditPage--;audits.reload()">上一页</button><span>第{{auditPage}}页</span><button :disabled="auditPage*20>=(audits.data.value?.total??0)" @click="auditPage++;audits.reload()">下一页</button></div></div></section></template>
